<?php
namespace App\Policies;
use App\Models\{Lead,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class LeadPolicy { use HandlesAuthorization,CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_lead');} public function view(User $u,Lead $r):bool{return $this->canForRecord($u,'view_lead',$r);} public function create(User $u):bool{return $u->can('create_lead');} public function update(User $u,Lead $r):bool{return $this->canForRecord($u,'update_lead',$r);} public function delete(User $u,Lead $r):bool{return $this->canForRecord($u,'delete_lead',$r);} public function deleteAny(User $u):bool{return $u->can('delete_any_lead');} public function restore(User $u,Lead $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function forceDelete(User $u,Lead $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function replicate(User $u,Lead $r):bool{return false;} public function reorder(User $u):bool{return false;} public function assign(User $u,Lead $r):bool{return $this->canForRecord($u,'assign_lead',$r);} }